  'Public Speaking',
  'This course develops students'' ability to design, research, organize, deliver, revise, and critique effective speeches for academic, civic, professional, online, and leadership contexts. Students practice audience analysis, topic development, research, evidence, outlining, storytelling, delivery, visual aids, informative speaking, persuasive speaking, ceremonial speaking, impromptu speaking, Q&A, ethics, accessibility, AI disclosure, and portfolio-based improvement.',
  $pspkjson${"slug": "public-speaking", "title": "Public Speaking", "description": "This course develops students' ability to design, research, organize, deliver, revise, and critique effective speeches for academic, civic, professional, online, and leadership contexts. Students practice audience analysis, topic development, research, evidence, outlining, storytelling, delivery, visual aids, informative speaking, persuasive speaking, ceremonial speaking, impromptu speaking, Q&A, ethics, accessibility, AI disclosure, and portfolio-based improvement.", "topics": [{"id": "e944d931-0bcb-4652-b1b3-7e3046debb1a", "type": "topic", "title": "Public Speaking Foundations: Communication, Audience, Purpose, and Context", "description": "Students learn public speaking as audience-centered, ethical, purposeful communication in academic, civic, professional, and digital contexts.", "children": [{"id": "471552d9-90e3-4a6d-a4ab-eefb51bb379f", "type": "subtopic", "title": "Public speaking as communication", "children": [{"id": "8f00700e-784c-4d91-a942-241b9eed94c0", "type": "concept", "title": "Sender, receiver, message, channel, feedback, noise, and context"}, {"id": "91a4e6af-dfd8-4647-a9ff-d17dd08279d5", "type": "concept", "title": "Academic, civic, professional, and digital speaking situations"}, {"id": "99612a22-4946-40d4-90fd-68e5396490eb", "type": "concept", "title": "Speech as dialogue, not performance only"}], "description": "The point is to see speeches as intentional communication among speaker, audience, message, and context."}, {"id": "e24654aa-0755-4e9c-96bd-945f6981b076", "type": "subtopic", "title": "Audience-centered speaking", "children": [{"id": "9d541ece-080b-4f1e-abad-46dc627cf6e6", "type": "concept", "title": "Audience needs, prior knowledge, motivation, and constraints"}, {"id": "d5a82674-81b2-4a08-b37e-7894feb24b96", "type": "concept", "title": "Relevance, credibility, and shared purpose"}, {"id": "52e914f1-98eb-4631-ab98-80e65fda980c", "type": "concept", "title": "Adapting without pandering or stereotyping"}], "description": "Students learn that strong speeches begin with the people who must understand and use the message."}, {"id": "d7603d24-927c-4f90-92f7-d597e7ae195b", "type": "subtopic", "title": "Speaking genres and purposes", "children": [{"id": "25e1ee1f-3a04-446e-ac0b-f21e67ee54ee", "type": "concept", "title": "Informative, persuasive, ceremonial, professional, and impromptu speaking"}, {"id": "35e7b223-d1d3-44c3-8928-15a5ef9ce5ad", "type": "concept", "title": "To explain, convince, inspire, honor, brief, or demonstrate"}, {"id": "1f9576ea-409d-4c76-b25b-6db573d53e6f", "type": "concept", "title": "Matching purpose to structure, tone, and evidence"}], "description": "Students distinguish what different speeches are trying to accomplish."}]}, {"id": "2bdd91c3-4d8f-4d85-808b-401ab0d7381d", "type": "topic", "title": "Speaker Confidence, Communication Apprehension, Presence, and Practice Habits", "description": "This topic builds confidence through preparation, rehearsal, self-awareness, feedback, and gradual performance practice.", "children": [{"id": "4ab14ff4-43d7-4cfa-8f6f-514891e21757", "type": "subtopic", "title": "Communication apprehension", "children": [{"id": "e7e026c5-e600-41f0-8237-4e178c5c50db", "type": "concept", "title": "Physical, cognitive, and situational symptoms"}, {"id": "64b38aff-3c50-4c06-9dba-b1ef3f5c7a4a", "type": "concept", "title": "Preparation, exposure, breathing, reframing, and visualization"}, {"id": "c004d7e3-1363-446c-bbb6-dcf3b38e4ae4", "type": "concept", "title": "Growth mindset and realistic self-assessment"}], "description": "Students learn to manage anxiety as a normal speaking challenge rather than a personal flaw."}, {"id": "25fd5425-fb30-4b9a-b0be-dadeda384fb0", "type": "subtopic", "title": "Speaker presence", "children": [{"id": "a5f047f6-05fc-4e0a-ba95-43c3fbe5720f", "type": "concept", "title": "Attention, grounding, pace, and composure"}, {"id": "65243459-1fbc-4599-82fc-9b59b33c2201", "type": "concept", "title": "Authenticity, authority, and warmth"}, {"id": "9142981c-7c88-40ae-90cd-b763cea6cc86", "type": "concept", "title": "Managing mistakes and recovering gracefully"}], "description": "Presence is the audience's sense that the speaker is prepared, engaged, and trustworthy."}, {"id": "22743082-c1aa-4086-b30b-65fecd69a6a6", "type": "subtopic", "title": "Practice systems", "children": [{"id": "36023a98-a7d9-40a9-824f-3503eedaf35c", "type": "concept", "title": "Timed rehearsals, recording, feedback, and revision"}, {"id": "c1a4e0a3-144a-4cb2-8723-92edcf6b7ca9", "type": "concept", "title": "Chunking, cueing, and memory aids"}, {"id": "a6744785-636c-4f06-aab9-c06c4a2c6b43", "type": "concept", "title": "Practice schedule and performance reflection"}], "description": "World-class speaking skill comes from deliberate rehearsal."}]}, {"id": "39af4193-1d42-4acf-98b9-a3c42c23f33b", "type": "topic", "title": "Audience Analysis, Listening, Inclusion, and Cultural Responsiveness", "description": "Students learn to adapt speeches to real audiences with respect for identity, access, expectations, and context.", "children": [{"id": "8af3f6a3-cef4-4b12-9e08-756fb7eb3485", "type": "subtopic", "title": "Audience analysis", "children": [{"id": "f400877a-cc9a-4cda-945b-64770c3013aa", "type": "concept", "title": "Demographics, psychographics, knowledge, attitudes, and context"}, {"id": "fb3c38ec-5e01-42dc-a49e-07322ee27612", "type": "concept", "title": "Stakeholder interests and likely objections"}, {"id": "79d9c57e-676f-49c5-9899-9eef6195b59a", "type": "concept", "title": "Pre-speech surveys, observation, and informal interviews"}], "description": "Students learn to research and infer what an audience needs before designing a speech."}, {"id": "2ef263ad-9ad8-48a6-8c9c-0c83d7c15a9d", "type": "subtopic", "title": "Listening and feedback", "children": [{"id": "e67df232-4b47-45ee-b1a3-a25ea00949fe", "type": "concept", "title": "Active listening, nonverbal audience cues, and feedback loops"}, {"id": "03b9d58b-01e8-4caf-9140-24dc4c823738", "type": "concept", "title": "Clarifying questions and response adaptation"}, {"id": "50cb3e8f-143b-45f2-b0e8-00cdb13a2119", "type": "concept", "title": "Peer critique as evidence for revision"}], "description": "Speaking improves when speakers can read and respond to audiences."}, {"id": "c7ed44c6-e926-4c83-a9d9-955895ff31c8", "type": "subtopic", "title": "Inclusive speaking", "children": [{"id": "457b17a2-22bf-4996-890b-f091410eb4ee", "type": "concept", "title": "Cultural responsiveness, inclusive language, and examples"}, {"id": "7d2e9820-3aea-4ec0-8cc2-9cf66bcacd4f", "type": "concept", "title": "Accessibility, captions, contrast, and plain language"}, {"id": "bd8a0d60-5660-4f30-85fe-e993bd6d4eeb", "type": "concept", "title": "Avoiding stereotypes, assumptions, and exclusionary humor"}], "description": "Students learn to make speeches accessible and respectful for diverse audiences."}]}, {"id": "58ce8fac-77aa-4881-ad0d-13536897e2e3", "type": "topic", "title": "Topic Selection, Purpose Statements, Theses, and Speech Goals", "description": "This module teaches students to turn broad interests into focused, meaningful, and achievable speech aims.", "children": [{"id": "50e0371f-b098-44e1-8416-7f2b6ca14632", "type": "subtopic", "title": "Topic discovery", "children": [{"id": "9624a381-dfda-4e30-b000-104f43b9ba7c", "type": "concept", "title": "Interest inventory, assignment fit, feasibility, and audience relevance"}, {"id": "b42353b1-3ad5-4add-8d3e-956e0237fb70", "type": "concept", "title": "Narrowing broad subjects"}, {"id": "6a834171-0b9d-418f-b055-69cbe99a22be", "type": "concept", "title": "Originality, timeliness, and scope"}], "description": "Students learn to choose topics with audience value and personal investment."}, {"id": "6894d322-8c7b-4d33-a4bc-fd60f0aafab8", "type": "subtopic", "title": "Purpose and thesis", "children": [{"id": "973d2f64-7ef5-466d-85aa-9dd8e107dcf0", "type": "concept", "title": "General purpose and specific purpose"}, {"id": "e94b8350-9d68-4b8b-9fc8-78f857dfa7b6", "type": "concept", "title": "Thesis statement, central idea, and preview"}, {"id": "ceb2d6b4-df24-4184-981b-6253852ed0cd", "type": "concept", "title": "Audience outcome and success criteria"}], "description": "The gist is to turn a topic into a clear promise to the audience."}, {"id": "fdcf30f5-7f8b-4615-a36e-91a87ad794ce", "type": "subtopic", "title": "Speech goals", "children": [{"id": "5561c650-6281-472d-a535-96076bb8629f", "type": "concept", "title": "Knowledge, attitude, behavior, emotion, or skill outcomes"}, {"id": "76494808-6537-4913-92fe-d9ad93a355d3", "type": "concept", "title": "Measurable objectives and realistic scope"}, {"id": "e625630a-411f-46e6-989b-71cb4652fda5", "type": "concept", "title": "Choosing depth over coverage"}], "description": "Students learn to define what should change for the audience."}]}, {"id": "341b39a8-b137-4570-a61d-5395d50650c0", "type": "topic", "title": "Research, Evidence, Source Evaluation, Citation, and Information Ethics", "description": "Students learn to find, evaluate, integrate, and cite credible support for public claims.", "children": [{"id": "4764b126-7ff0-4827-b250-e4cfe6d0a840", "type": "subtopic", "title": "Research process", "children": [{"id": "cc3793f9-79e1-495c-8f06-d71cab8fee2f", "type": "concept", "title": "Research questions, keywords, databases, expert sources, and interviews"}, {"id": "b9e2a8e6-b96d-4e3e-a6a8-6b21ba421ed7", "type": "concept", "title": "Primary and secondary sources"}, {"id": "cf65900f-5787-4331-912f-75cbb633c6b3", "type": "concept", "title": "Source diversity and recency"}], "description": "Students learn to build speeches on credible and relevant evidence."}, {"id": "b392fefc-6c14-4123-a24b-0f69f490a9b7", "type": "subtopic", "title": "Evidence evaluation", "children": [{"id": "07c227f7-e15f-427b-9b5d-5bf59acd8673", "type": "concept", "title": "Authority, accuracy, bias, currency, relevance, and method"}, {"id": "66801d51-295f-44e0-bf57-8099d62cf64d", "type": "concept", "title": "Statistics, examples, testimony, analogies, and narratives"}, {"id": "39eca597-792c-4fdd-aede-80be1f6c08d6", "type": "concept", "title": "Fact-checking and lateral reading"}], "description": "The point is to avoid weak, misleading, or unsupported claims."}, {"id": "735515d3-a281-4da0-84ba-381a59dd7465", "type": "subtopic", "title": "Citation and ethics", "children": [{"id": "eff489d9-e9c1-4b1b-80a2-5cca02398c70", "type": "concept", "title": "Oral citations and written references"}, {"id": "f1a7474b-d4c3-4c8c-9e59-0e68d885be49", "type": "concept", "title": "Paraphrasing, quoting, plagiarism, and AI disclosure"}, {"id": "bbbd6a59-8f76-4edb-9563-9e25cf8e7eb2", "type": "concept", "title": "Respecting context, data, and intellectual property"}], "description": "Students practice transparent source use."}]}, {"id": "dd109e38-8624-4919-b83e-3df5415ff883", "type": "topic", "title": "Speech Organization, Outlining, Introductions, Transitions, and Conclusions", "description": "This topic develops clear structure so audiences can follow, remember, and act on ideas.", "children": [{"id": "12682206-f4c3-436d-b127-5a689b954d9d", "type": "subtopic", "title": "Organizational patterns", "children": [{"id": "7aaba2ee-fd1f-40c8-9524-83a7f5ff2cc1", "type": "concept", "title": "Chronological, spatial, topical, causal, problem-solution, Monroe's motivated sequence, and comparative structures"}, {"id": "9411fc48-84bc-4aa5-be1c-308dc0758133", "type": "concept", "title": "Main points and subpoints"}, {"id": "a5f274c5-a24b-49e0-9598-d9c0056feb99", "type": "concept", "title": "Balance, hierarchy, and flow"}], "description": "Students learn to choose a structure that fits the purpose."}, {"id": "f9b2142e-6e3b-4726-b061-1eff66b5d372", "type": "subtopic", "title": "Introductions and conclusions", "children": [{"id": "65706e7f-7b6a-4b36-9fe0-8f6f69af70ab", "type": "concept", "title": "Attention getter, relevance, credibility, thesis, and preview"}, {"id": "92d20326-86b5-4f3d-895d-e5b379fafe4a", "type": "concept", "title": "Summary, closure, clincher, and final call to action"}, {"id": "f67655f1-f83d-4cb0-bd94-16348cdc5579", "type": "concept", "title": "Avoiding false starts and weak endings"}], "description": "Openings and endings shape attention and memory."}, {"id": "83e4e4ce-3cf2-4b09-a77c-71a5bbd1f488", "type": "subtopic", "title": "Outlines and transitions", "children": [{"id": "a79a4ef3-478d-474a-82f3-3ff0100efb7d", "type": "concept", "title": "Preparation outlines and speaking outlines"}, {"id": "646ceeeb-6e0e-4e8d-84ad-56c63d4b0753", "type": "concept", "title": "Internal previews, signposts, summaries, and transitions"}, {"id": "f50d5200-aebd-41d7-afbe-0a1d7fe134fe", "type": "concept", "title": "Cue cards, notes, and memory supports"}], "description": "Outlines help speakers design and audiences follow."}]}, {"id": "b955a6bf-0a21-4b7f-a21d-488072210609", "type": "topic", "title": "Language, Style, Clarity, Storytelling, and Memorable Message Design", "description": "Students learn to shape language for precision, vividness, rhythm, accessibility, and audience memory.", "children": [{"id": "b13bbd35-a4e2-496c-8861-216e864ae556", "type": "subtopic", "title": "Clear language", "children": [{"id": "e6f42ba0-eaa9-49ab-ac5d-34d662dd83b6", "type": "concept", "title": "Concrete words, active verbs, short sentences, and definitions"}, {"id": "9366f5db-4e2e-4b14-8844-e1d56dd55a8f", "type": "concept", "title": "Jargon control and plain language"}, {"id": "2c4bb869-a4fe-47dc-bb30-48fbf8762249", "type": "concept", "title": "Precision, concision, and audience fit"}], "description": "Students learn to make ideas easy to process without flattening complexity."}, {"id": "bcda04c5-9920-4129-8b45-6fca488b647d", "type": "subtopic", "title": "Rhetorical style", "children": [{"id": "5edc033a-9d85-4ec2-8772-4eaef0258c14", "type": "concept", "title": "Repetition, parallelism, contrast, metaphor, analogy, and rhythm"}, {"id": "25c1d0f8-aa14-42de-b1f1-2c33243bc353", "type": "concept", "title": "Humor, vivid imagery, and sensory detail"}, {"id": "480b5945-2c8a-4c3f-b0b8-3a9ad6350d47", "type": "concept", "title": "Tone, register, and voice"}], "description": "Style helps speeches sound memorable and intentional."}, {"id": "2001f7b9-3997-480f-9bcf-9c2eb056188d", "type": "subtopic", "title": "Storytelling", "children": [{"id": "fe063a7e-21c0-4ba0-bd38-1b4b0967ae0b", "type": "concept", "title": "Character, conflict, stakes, turning point, and resolution"}, {"id": "23c65bac-8193-477a-8806-46bbbbbf67a3", "type": "concept", "title": "Personal stories, case stories, and audience stories"}, {"id": "3672f58f-8d38-4bad-af21-5c9d5b31aa9f", "type": "concept", "title": "Ethical storytelling and avoiding exploitation"}], "description": "Stories make ideas human, memorable, and emotionally legible."}]}, {"id": "c432b945-2783-4357-8706-5e93bd79d95b", "type": "topic", "title": "Delivery: Voice, Body, Eye Contact, Movement, Timing, and Energy", "description": "This module develops embodied delivery choices that support credibility, connection, and clarity.", "children": [{"id": "36f7d884-6a0e-4899-8484-23af4ff85e04", "type": "subtopic", "title": "Vocal delivery", "children": [{"id": "875a7a0b-9374-4328-9c70-8343e1753f2a", "type": "concept", "title": "Volume, rate, pitch, pauses, articulation, and vocal variety"}, {"id": "1746de33-09d6-4f82-ba72-47d35468889a", "type": "concept", "title": "Emphasis, phrasing, and silence"}, {"id": "b334dbfd-ef53-47e2-8b69-5f25797c7366", "type": "concept", "title": "Microphone technique and vocal care"}], "description": "Voice carries meaning, emotion, emphasis, and credibility."}, {"id": "9d43d19c-8139-4ac7-8424-8ec81a7f5846", "type": "subtopic", "title": "Physical delivery", "children": [{"id": "0c579de3-a1b3-4294-a16d-95b26e24da05", "type": "concept", "title": "Posture, gesture, facial expression, movement, and eye contact"}, {"id": "e0f95560-6df0-4328-ab44-0612cb54ed25", "type": "concept", "title": "Stage position and audience connection"}, {"id": "a950019c-febf-46f0-a08a-ed8ae3122f7d", "type": "concept", "title": "Managing habits, fidgeting, and nervous movement"}], "description": "Body language should support the message rather than distract from it."}, {"id": "c30466ff-e009-4c3b-a809-60015de653c4", "type": "subtopic", "title": "Timing and energy", "children": [{"id": "a91c0618-66cd-45d8-ac9d-0f12c211c9d2", "type": "concept", "title": "Pacing, pauses, transitions, and time limits"}, {"id": "ff8d8728-ef14-4ea0-9543-0b5a2f9c0be9", "type": "concept", "title": "Energy shifts and audience resets"}, {"id": "7276756e-c163-4238-877a-ea83f9f4e670", "type": "concept", "title": "Adapting delivery to room, audience, and format"}], "description": "Students learn to manage the audience's attention over time."}]}, {"id": "70db7294-abf4-4055-af02-d06712db23f2", "type": "topic", "title": "Visual Aids, Slide Design, Presentation Technology, and Data Storytelling", "description": "Students learn to use visuals and technology as aids to understanding rather than decoration.", "children": [{"id": "69d5772e-8d21-4a36-a252-74ee4a99b9cc", "type": "subtopic", "title": "Visual aid principles", "children": [{"id": "c1e0d5b6-98f7-47f6-9938-86fb75e29a54", "type": "concept", "title": "Purpose, relevance, simplicity, and visual hierarchy"}, {"id": "7a6293dc-982d-421a-aaa7-7ab67a9b7077", "type": "concept", "title": "Images, diagrams, objects, props, charts, and demonstrations"}, {"id": "0f5f20a0-9a19-4137-b951-062b08dfc4c0", "type": "concept", "title": "Accessibility, contrast, size, and readability"}], "description": "Students learn that visuals should clarify, not compete."}, {"id": "d9c4c1a8-6e8d-4760-a80d-1df8b8e06af2", "type": "subtopic", "title": "Slide design", "children": [{"id": "6370ad08-1464-4ba6-aebe-334410f4a530", "type": "concept", "title": "One idea per slide, minimal text, strong layout, and consistent design"}, {"id": "02415017-4b3f-4566-906f-e10c54600182", "type": "concept", "title": "Titles, images, icons, and whitespace"}, {"id": "a3b3a26d-3130-4d03-aa6d-f90fbc1f988e", "type": "concept", "title": "Avoiding clutter, tiny text, and decoration without purpose"}], "description": "Good slides support the spoken message rather than becoming speaker notes."}, {"id": "56437120-d027-4641-b2cf-cb545529b33f", "type": "subtopic", "title": "Technology and data", "children": [{"id": "e69d9e9b-8d34-4649-960f-7131ca298473", "type": "concept", "title": "Presentation software, remote clickers, video, polls, and backup plans"}, {"id": "9bf5c644-da3f-48e5-b9d9-c3f49c1e10ab", "type": "concept", "title": "Charts, numbers, comparisons, and uncertainty"}, {"id": "49b2b102-2048-4963-8f93-b4ede67c7f31", "type": "concept", "title": "Data storytelling and source labeling"}], "description": "Students practice using tools and data responsibly."}]}, {"id": "8bc7d15e-b476-4ad3-b044-fcb03565d425", "type": "topic", "title": "Informative Speaking, Demonstrations, Explanations, and Teaching Complex Ideas", "description": "This topic focuses on speeches that explain, teach, demonstrate, or clarify unfamiliar material.", "children": [{"id": "18fa5db4-939d-449c-9d80-7a71b0778a2f", "type": "subtopic", "title": "Informative speech design", "children": [{"id": "88b7f0e5-a80e-47fe-a1e7-63f8418be0a9", "type": "concept", "title": "Definitions, processes, concepts, events, and objects"}, {"id": "9baaa367-0d15-4828-ba01-73a6b07cee51", "type": "concept", "title": "Layering information from simple to complex"}, {"id": "6434cb36-6c3d-4cb6-a526-436e7ad33a95", "type": "concept", "title": "Examples, analogies, and checks for understanding"}], "description": "Students learn to teach without overwhelming."}, {"id": "833f099d-4b91-429c-a839-a2ef6ec3af11", "type": "subtopic", "title": "Demonstration speeches", "children": [{"id": "b9284a60-ccb1-47ce-95ce-74224f9de51c", "type": "concept", "title": "Materials, steps, timing, and audience view"}, {"id": "57b52901-794c-463f-9863-b81420fbfe06", "type": "concept", "title": "Explaining why each step matters"}, {"id": "c2d92575-390a-4fc1-8821-828a9946c23d", "type": "concept", "title": "Troubleshooting and contingency planning"}], "description": "Demonstrations require sequencing, visibility, and safety."}, {"id": "58f20089-e963-4928-8360-ce6316c68392", "type": "subtopic", "title": "Explaining complexity", "children": [{"id": "0442bfc7-88d1-4990-80cb-ce5b50624838", "type": "concept", "title": "Chunking, metaphors, visuals, and stories"}, {"id": "a3b819a0-9098-4b1c-bde6-216993e79d34", "type": "concept", "title": "Avoiding oversimplification"}, {"id": "f8ec7740-9604-4e75-b8b5-9e3774ee1f24", "type": "concept", "title": "Signposting key takeaways"}], "description": "Students practice making technical or abstract ideas accessible."}]}, {"id": "7828d0c9-c445-4fca-8afc-ac6df68256db", "type": "topic", "title": "Persuasive Speaking, Argumentation, Rhetoric, and Calls to Action", "description": "Students learn to ethically influence audiences through claims, evidence, reasoning, emotion, and action design.", "children": [{"id": "7466b0c4-c182-4a03-a999-fc949fd50858", "type": "subtopic", "title": "Persuasive foundations", "children": [{"id": "bd93f921-5f12-4d66-a3ac-807df90662cb", "type": "concept", "title": "Ethos, logos, pathos, and kairos"}, {"id": "b4b14203-786d-476e-8453-9364e509c374", "type": "concept", "title": "Attitudes, motivation, social proof, and resistance"}, {"id": "9855106c-2f41-4911-b0fb-416c479d3a2d", "type": "concept", "title": "Ethical influence and audience autonomy"}], "description": "Students learn how audiences change beliefs, attitudes, and behavior."}, {"id": "787ffcac-5fb5-4f93-953d-3c1dce61a493", "type": "subtopic", "title": "Argumentation", "children": [{"id": "d7c9392b-486a-4ac8-b407-72a612c7c6ba", "type": "concept", "title": "Claims of fact, value, and policy"}, {"id": "5b070882-b4b2-4fd3-9cb0-ca202809b6c5", "type": "concept", "title": "Evidence, warrants, counterarguments, and refutation"}, {"id": "ed7e5e0e-3237-4f36-b45c-4ef984f66355", "type": "concept", "title": "Logical fallacies and weak reasoning"}], "description": "Persuasive claims need evidence and reasoning."}, {"id": "d864bbc3-eecf-4499-8e51-4175bdd4d028", "type": "subtopic", "title": "Calls to action", "children": [{"id": "32fc613b-05e7-43b7-bb31-d26a729b8186", "type": "concept", "title": "Specific actions, barriers, benefits, and urgency"}, {"id": "4ff2f852-5d67-4dcb-a781-4f021007e59e", "type": "concept", "title": "Monroe's motivated sequence"}, {"id": "3569b3d7-f3e3-44f0-92e4-1a34d35a82e5", "type": "concept", "title": "Commitment, follow-up, and audience agency"}], "description": "Students learn to make action clear and realistic."}]}, {"id": "68e19e58-5e95-44d5-9e68-f88f27a9c0fa", "type": "topic", "title": "Special Occasion, Ceremonial, Narrative, and Professional Speeches", "description": "This module prepares students for speeches that honor, introduce, commemorate, pitch, brief, or represent a group.", "children": [{"id": "ff4866c0-cce0-42b6-84f2-5c5e644a3fb9", "type": "subtopic", "title": "Ceremonial speaking", "children": [{"id": "633b8f10-5351-42a7-8429-3c95fe2e16e3", "type": "concept", "title": "Introductions, toasts, tributes, commemorations, and award speeches"}, {"id": "6f28eb07-d873-4f58-891b-94232f7c08b1", "type": "concept", "title": "Tone, brevity, sincerity, and audience expectations"}, {"id": "fd0a2636-8bce-48a3-b390-02282c54f7cb", "type": "concept", "title": "Representing people and communities with care"}], "description": "Ceremonial speeches use language to honor, remember, welcome, or celebrate."}, {"id": "9c5ebfae-4c20-48fd-a3b2-32696db2734b", "type": "subtopic", "title": "Narrative speeches", "children": [{"id": "24a5dc0b-2323-43c9-b20a-40ce3aa25570", "type": "concept", "title": "Scene, character, conflict, reflection, and lesson"}, {"id": "31601df2-87be-4d48-bd5d-0c32b3593741", "type": "concept", "title": "Personal disclosure and boundaries"}, {"id": "0798e339-5e75-402c-9688-d45ff3cca3f2", "type": "concept", "title": "Story structure and audience relevance"}], "description": "Narrative speaking turns experience into meaning."}, {"id": "88240e6b-0885-44e2-adda-889644fdc3d7", "type": "subtopic", "title": "Professional speeches", "children": [{"id": "560dd5f2-cf9e-455f-b9ed-bf60005ef9b3", "type": "concept", "title": "Briefings, pitches, status updates, trainings, and interviews"}, {"id": "bb9fb496-3dd6-4ed8-97bd-b821117f8179", "type": "concept", "title": "Executive summaries and recommendation speeches"}, {"id": "06e5cf38-abe2-496e-adc4-b9b7026a4dd8", "type": "concept", "title": "Professional tone and credibility"}], "description": "Students prepare for workplace and public-facing speaking."}]}, {"id": "bb76a554-4260-427a-8386-a44d747e70a9", "type": "topic", "title": "Impromptu, Extemporaneous, Q&A, Panels, Meetings, and Online Presentations", "description": "Students practice flexible speaking in live, hybrid, virtual, and interactive settings.", "children": [{"id": "7565b459-f969-4124-a0f7-3cebadd7e75d", "type": "subtopic", "title": "Impromptu speaking", "children": [{"id": "223d717f-be16-421b-8824-40dad954e76f", "type": "concept", "title": "PREP, STAR, problem-solution, and point-reason-example structures"}, {"id": "de7b4fce-20d4-4b5c-bf80-f2fa6f908152", "type": "concept", "title": "Thinking aloud with clarity"}, {"id": "4765c25f-1b04-4487-b998-b4aa33b85b4d", "type": "concept", "title": "Managing pressure and time"}], "description": "Students build flexible speaking habits for unexpected moments."}, {"id": "33b92812-d476-4e83-a9e5-3d356c2e06e7", "type": "subtopic", "title": "Interactive formats", "children": [{"id": "8e29964b-7283-46f7-b41a-c540ec0fe1bb", "type": "concept", "title": "Q&A, panels, meetings, facilitation, and group presentations"}, {"id": "08d4ec4c-020e-45cb-ab4f-4b11bedf8ac6", "type": "concept", "title": "Responding to objections and difficult questions"}, {"id": "5e40a23a-4e9b-434e-998d-6fa1053bb023", "type": "concept", "title": "Turn-taking, summarizing, and redirecting"}], "description": "Speaking often happens in dialogue rather than monologue."}, {"id": "80f4fad9-5b3d-4103-96e1-e9558330a50c", "type": "subtopic", "title": "Online and hybrid presentations", "children": [{"id": "cb5c4162-bab6-4824-b821-4974fa86eaf7", "type": "concept", "title": "Camera, lighting, audio, framing, and chat"}, {"id": "83635fc4-4755-4e73-bbcd-8f1540045673", "type": "concept", "title": "Screen sharing, polls, and audience interaction"}, {"id": "c9caefb7-c134-4536-8f82-8a5201dd8b6d", "type": "concept", "title": "Hybrid equity and backup plans"}], "description": "Digital delivery requires deliberate presence and technical planning."}]}, {"id": "dc38edfe-8ccd-4463-8e92-90f01ee889dd", "type": "topic", "title": "Ethics, Credibility, Accessibility, AI, Speech Law, and Responsible Influence", "description": "This topic builds judgment around truthfulness, attribution, inclusion, disclosure, free speech, and responsible persuasion.", "children": [{"id": "021461e3-5384-4ab0-b98c-f83203d1deb6", "type": "subtopic", "title": "Speaker ethics", "children": [{"id": "010a9649-8c3a-438b-938c-217f601a2d79", "type": "concept", "title": "Truthfulness, fairness, attribution, and respect"}, {"id": "fa1134c8-4f67-4b21-a936-86bf3586a3ef", "type": "concept", "title": "Avoiding deception, manipulation, and harmful stereotypes"}, {"id": "860dff9c-eb1d-4e20-94e2-7ba3379a54ea", "type": "concept", "title": "Disclosure of conflicts, AI assistance, and uncertainty"}], "description": "Students learn the responsibilities that come with audience attention."}, {"id": "ff95f170-5efa-47b3-8999-6573ed0bbca3", "type": "subtopic", "title": "Credibility and trust", "children": [{"id": "03a2661a-2cfd-4a30-bf16-32373971ccf9", "type": "concept", "title": "Competence, character, care, and transparency"}, {"id": "d2a0694e-dc6e-4b08-ac9b-04849be036fa", "type": "concept", "title": "Evidence quality and source credibility"}, {"id": "3a3ee40c-2bc1-4a2d-b5a1-896a775f8eaa", "type": "concept", "title": "Handling errors and corrections"}], "description": "Credibility is earned before, during, and after a speech."}, {"id": "5c7c07f6-96a5-4b0d-a981-8d1df77ec5dc", "type": "subtopic", "title": "Speech rights and responsibilities", "children": [{"id": "e87a36b7-4d14-4fb0-a14a-6cfc9c67a037", "type": "concept", "title": "Free speech, hate speech debates, academic contexts, and institutional policies"}, {"id": "26764901-2078-4548-bc4c-991ba65e0fc8", "type": "concept", "title": "Commercial speech and public advocacy"}, {"id": "4c3cf898-b8ec-4c03-a0f5-61f107f7ca9d", "type": "concept", "title": "Accessibility, inclusion, and audience safety"}], "description": "Students learn the boundaries and stakes of public expression."}]}, {"id": "13369fb8-7dc4-427d-baad-36b2b2244e47", "type": "topic", "title": "Speech Portfolio, Peer Critique, Revision, and Final Presentation Capstone", "description": "Students synthesize the course through iterative practice, critique, revision, and a polished final presentation portfolio.", "children": [{"id": "811550cf-9aa6-4d3f-b714-6dbc7d69075a", "type": "subtopic", "title": "Portfolio curation", "children": [{"id": "91833f56-3db3-45dc-b9de-c27e61ac4fd5", "type": "concept", "title": "Outlines, scripts, slides, recordings, reflections, and feedback"}, {"id": "37512e67-a897-418b-942a-0926b148ed5c", "type": "concept", "title": "Informative, persuasive, professional, and impromptu artifacts"}, {"id": "08f25039-9ec6-4bd2-b7bd-83f1c8d4a9e0", "type": "concept", "title": "Selecting and revising strongest work"}], "description": "Students collect evidence of growth across speaking situations."}, {"id": "b21de8f9-8820-41d8-a96c-0d0db8224003", "type": "subtopic", "title": "Peer critique", "children": [{"id": "f1fbb770-a15c-42fa-9596-4b46858c180d", "type": "concept", "title": "Descriptive, constructive, criteria-based feedback"}, {"id": "fd61754a-ecca-4551-8e0a-6fc460d32981", "type": "concept", "title": "Delivery, structure, evidence, visuals, and audience connection"}, {"id": "9bd4cadd-6f08-43a3-8f4b-5ee3d9ea1dd8", "type": "concept", "title": "Giving and receiving critique professionally"}], "description": "Feedback teaches students to diagnose speaking choices with specificity."}, {"id": "6af861a3-cbf5-4d95-ba9b-df0ea9569b5b", "type": "subtopic", "title": "Final capstone", "children": [{"id": "e8ffb9c7-5516-4623-ba8e-b568dac485b8", "type": "concept", "title": "Capstone topic and audience rationale"}, {"id": "6dab57c8-796d-47fe-af3b-77e674968fcb", "type": "concept", "title": "Polished delivery and visual support"}, {"id": "5cef97fd-8ca8-42ba-aba4-b96d9beabb4d", "type": "concept", "title": "Post-speech reflection and future speaking plan"}], "description": "The final presentation integrates research, structure, style, delivery, visuals, ethics, and revision."}]}], "dbBacked": true}$pspkjson$::jsonb,
